<script setup lang="ts">
const supabase=useSupabaseClient(); const password=ref(''); const confirmPassword=ref(''); const loading=ref(false); const error=ref(''); const message=ref(''); const ready=ref(false)
onMounted(async()=>{const {data}=await supabase.auth.getSession(); ready.value=!!data.session; if(!ready.value){await new Promise(r=>setTimeout(r,800)); const second=await supabase.auth.getSession(); ready.value=!!second.data.session}})
async function updatePassword(){error.value='';message.value='';if(password.value.length<8)return error.value='Password must be at least 8 characters.';if(password.value!==confirmPassword.value)return error.value='Passwords do not match.';loading.value=true;const {error:e}=await supabase.auth.updateUser({password:password.value});loading.value=false;if(e)return error.value=e.message;message.value='Password updated successfully. You can now continue to your Host Dashboard.'}
</script>
<template><main class="neon-page grid place-items-center px-4 py-10"><div class="w-full max-w-md"><img src="/kc-jukebox-logo.png" class="neon-logo max-w-[210px]" alt="KC Jukebox"><section class="neon-card mt-5 p-7 sm:p-8"><div class="text-center"><div class="neon-kicker">Secure Recovery</div><h1 class="neon-title mt-2 text-3xl">Choose New Password</h1></div><div v-if="!ready" class="mt-7 rounded-xl border border-amber-500/30 bg-amber-500/10 p-4 text-sm text-amber-200">Open this page using the password reset link from your email. If you just clicked it, refresh once the secure session has loaded.</div><form v-else class="mt-7 space-y-4" @submit.prevent="updatePassword"><div><label class="mb-2 block text-sm font-bold text-slate-300">New password</label><input v-model="password" class="neon-input" type="password" autocomplete="new-password" required></div><div><label class="mb-2 block text-sm font-bold text-slate-300">Confirm password</label><input v-model="confirmPassword" class="neon-input" type="password" autocomplete="new-password" required></div><div v-if="error" class="rounded-xl border border-red-500/30 bg-red-500/10 p-3 text-sm text-red-300">{{error}}</div><div v-if="message" class="rounded-xl border border-green-500/30 bg-green-500/10 p-3 text-sm text-green-300">{{message}}</div><button class="neon-btn w-full" :disabled="loading">{{loading?'Updating…':'Update Password'}}</button><NuxtLink v-if="message" to="/host" class="neon-btn-cyan block w-full text-center">Continue to Host Dashboard</NuxtLink></form></section></div></main></template>
